      "p1": "In plain terms, I design and ship <b>software systems that automate complex workflows reliably and verifiably</b>—from desktop AI copilots that see your screen and translate live speech under 250ms, to cloud accounting suites, content studios, and commercial games. Under the hood, I specialize in <b>distributed microservices, deterministic state machines, GPU-accelerated multimodal pipelines, and empirical quality gates</b> built on C# .NET 10, Python FastAPI, vector search, and zero-allocation runtime tuning.",
      "p2": "Over recent years, I have engineered and shipped <b>18 complete software products</b> end to end: citation-verified research & publishing pipelines (69K LOC), desktop fly-by-wire AI copilots, CUDA speech translation HUDs, Zoho Books Clone (118-page cloud accounting), ZarDigit AP suite, Auro command center, NitroLango (72 lessons), UniversalSystem automation platform, and commercially released mobile games.",
