      "p2": "In den letzten Jahren habe ich <b>18 vollständige Softwaresysteme</b> vom Konzept bis zur Produktion umgesetzt: zitiergeprüfte Dokumentenerstellung (69K LOC), autonome Desktop-Copiloten, CUDA-Übersetzungs-HUDs, Zoho-Books-Klon (118 Seiten), ZarDigit-Finanzplattform, Auro-Kontrollzentrum, NitroLango (72 Lektionen), UniversalSystem und veröffentlichte Mobile-Games.",
