    "gate": {
      "title": "Das 5-Punkte-Verifikations-Gate",
      "sub": "Manifest für halluzinationsfreie & defensive Software-Architektur",
      "intro": "Viele Systeme schweigen bei Fehlern oder melden fälschlich Erfolg. Mein Grundprinzip lautet: Keine Software und kein KI-Agent darf eine Aufgabe als erledigt melden ohne messbaren Live-Beweis. Fünf verbindliche Regeln sichern jedes meiner Systeme ab:",
      "points": [
        {
          "num": "1",
          "t": "Empirische Beweispflicht (Keine Spekulation)",
          "d": "Nichts gilt als fertig ohne Exit-Code 0, null Compilerfehler, konkrete Dateipfade/Zeilen und verifizierte Laufzeitausgabe. Vage Aussagen wie 'sollte funktionieren' sind ausgeschlossen."
        },
        {
          "num": "2",
          "t": "Defensive Grenzprüfung aller Zustände",
          "d": "Verpflichtende Schutzprüfungen gegen NaN, Infinity und Bereichsüberschreitungen vor dem Schreiben von Physikvektoren, Positionen oder Kontosalden."
        },
        {
          "num": "3",
          "t": "Zero-GC-Regel in heißen Schleifen",
          "d": "In hochfrequenten Update-, Frame-Diffing- und Audio-Loops sind Objektallokationen (new), String-Verkettungen und LINQ untersagt; Shader-IDs werden vorab zwischengespeichert."
        },
        {
          "num": "4",
          "t": "Robuste Watchdog-Wiederherstellung",
          "d": "Feste Timeouts (z. B. 15 Sekunden) schützen WebSockets, Browser-Spracherkennung und Warteschlangen, sodass Benutzeroberflächen niemals einfrieren."
        },
        {
          "num": "5",
          "t": "Fail-Closed-Sicherheit & HMAC-Protokolle",
          "d": "Zugangsdaten werden niemals im Klartext protokolliert — Inspektionen zeigen nur Name und Länge — und jede Aktion wandert in verkettete HMAC-Prüfbücher."
        }
      ]
    },
