      "title": "Resumen Ejecutivo — Claro para Directivos, Preciso para Ingenieros",
      "sub": "Uniendo modelos de IA avanzados con ingeniería de software de producción",
      "p1": "En términos claros, diseño y entrego <b>sistemas que automatizan procesos complejos con fiabilidad comprobable</b>: desde copilotos de escritorio con visión de pantalla y traducción en menos de 250 ms hasta suites contables en la nube, estudios de contenido y videojuegos comerciales. A nivel técnico me especializo en <b>microservicios distribuidos, máquinas de estados, pipelines multimodales en GPU y optimización sin pausas de memoria</b> sobre C# .NET 10, Python FastAPI y búsqueda vectorial.",
      "p2": "En los últimos años he diseñado y desplegado <b>18 sistemas completos de principio a fin</b>: publicación verificada (69K líneas), copilotos autónomos en Windows, traductores CUDA en vivo, clon de Zoho Books (118 páginas), plataforma financiera ZarDigit, centro de mando Auro, NitroLango (72 lecciones), UniversalSystem y títulos móviles publicados.",
